const { sendMessage } = require('../handles/sendMessage');

const L = '───────────────────────────────────';

function formatWork(position, company, years, duties) {
  const spaces = ' '.repeat(Math.max(0, 58 - position.length));
  return position + spaces + years + '\n' + company + '\n\n' + duties;
}

function createResume(gender, birthdate, civilStatus, languages, summary, education, skills, workList, references) {
  const header = 'JUAN DELA CRUZ (example lang — palitan mo ng actual name)\nEmail: juandelacruz@gmail.com | Contact No.: 09123456789 | Address: Muntinlupa City, Philippines\n\n';
  const workSection = workList.join('\n\n');
  return header + L + '\n\nPROFESSIONAL SUMMARY\n\n' + summary + '\n\n' + L + '\n\nPERSONAL PROFILE\n\n· Gender: ' + gender + '\n· Nationality: Filipino\n· Date of Birth: ' + birthdate + '\n· Religion: Roman Catholic\n· Civil Status: ' + civilStatus + '\n· Language Spoken: ' + languages + '\n\n' + L + '\n\nWORK EXPERIENCES\n\n' + workSection + '\n\n' + L + '\n\nEDUCATION\n\n' + education + '\n\n' + L + '\n\nSKILLS\n\n' + skills + '\n\n' + L + '\n\nREFERENCES\n\n' + references;
}

